cription":"FRESH CHICKEN DRUMSTICK","material":"10089827","qty":6.9}]},{"id":"e_1793357187848_xojjhn","created_at":"2026-10-30T10:46:27.848Z","staff":"NIZAM","supervisor":"KAHLISTINAH","base_plu":"50083","base_description":"CHICKEN LEG QUARTER","base_material":"10056837","base_qty":22.4,"total_cut_qty":22.33,"difference":0.07,"status":"completed","material_doc_a":"4901833660","material_doc_b":"1000020726","weight_discrepancy_doc":"4901833661","keyed_in_by":"KIRK","keyed_in_at":"2026-10-31T15:22:00+08:00","cuts":[{"position":1,"plu":"50049","description":"FRESH CHICKEN DRUMSTICK","material":"10089827","qty":9.48},{"position":2,"plu":"50053","description":"FRESH CHICKEN THIGH","material":"10089831","qty":12.85}]}]'::jsonb) as t (id text, created_at timestamptz, staff text, supervisor text, base_plu text, base_description text, base_material text, base_qty numeric, total_cut_qty numeric, difference numeric, status text, material_doc_a text, material_doc_b text, weight_discrepancy_doc text, keyed_in_by text, keyed_in_at timestamptz, cuts jsonb)
),
new_entries as (
  insert into cc_entries (id, created_at, staff, supervisor, base_plu, base_description, base_material, base_qty, total_cut_qty, difference, status, material_doc_a, material_doc_b, weight_discrepancy_doc, keyed_in_by, keyed_in_at)
  select id, created_at, staff, supervisor, base_plu, base_description, base_material, base_qty, total_cut_qty, difference, status, material_doc_a, material_doc_b, weight_discrepancy_doc, keyed_in_by, keyed_in_at
  from data
  on conflict (id) do nothing
  returning id
)
insert into cc_entry_cuts (entry_id, position, plu, description, material, qty)
select d.id, c.position, c.plu, c.description, c.material, c.qty
from data d
join new_entries n on n.id = d.id
cross join lateral jsonb_to_recordset(d.cuts) as c (position int, plu text, description text, material text, qty numeric);

select (select count(*) from cc_entries) as entries, (select count(*) from cc_entry_cuts) as cut_lines;
